INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f14e3960-2b58-4aa0-b61a-75d04f3095a6', '6e179e6c-f2e3-44b2-bda2-9a72f8c7df04', 0, 'An unspecified injury code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58698167-f53c-4dfd-a2f5-063f83155382', '6e179e6c-f2e3-44b2-bda2-9a72f8c7df04', 1, 'The outcome of delivery (e.g., a code reflecting single liveborn delivery), reported per the guideline directing an outcome-of-delivery code be included on the mother''s obstetric record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c9a306c-1f3b-4520-9330-07347eb60f00', '6e179e6c-f2e3-44b2-bda2-9a72f8c7df04', 2, 'Only a well-child visit code, since the infant is healthy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4bfb81df-8e7a-4bf5-befe-7bcf81413810', '6e179e6c-f2e3-44b2-bda2-9a72f8c7df04', 3, 'No code at all, since the delivery was uncomplicated');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecf8004a-34aa-40d6-bf1e-1b158596131c', '26b0168a-bede-4427-b0b7-bbff38e66b5c', 0, 'Trimester is never a coding element in obstetric ICD-10-CM codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9463f4bb-9a17-4383-b5bc-7cd55d804eaf', '26b0168a-bede-4427-b0b7-bbff38e66b5c', 1, 'Many obstetric codes include a character indicating the trimester (first, second, third, or unspecified) during which the documented condition occurred or is being managed, meaning correct code assignment depends on knowing which trimester applies at the time of the encounter, not just at conception');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd40e88c-aa20-49b5-9e6f-4322b8734a8a', '26b0168a-bede-4427-b0b7-bbff38e66b5c', 2, 'Trimester always refers to the trimester of the mother''s LAST pregnancy, not the current one');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02ed1b81-d655-47c5-9ea5-ee45d0dbf641', '26b0168a-bede-4427-b0b7-bbff38e66b5c', 3, 'Trimester coding applies only to codes for congenital anomalies of the fetus');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf6c2372-5597-4410-b844-46b2c433a3fd', '34185817-e72e-418a-857f-6c6ebfc862b8', 0, 'The complication of pregnancy (preeclampsia) is sequenced as principal diagnosis, since Chapter 15 guidelines generally direct that obstetric complications be sequenced first when they are the reason for the encounter/procedure, with the outcome-of-delivery code and procedure code(s) also assigned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd811420-a07c-4374-aa65-984c0c19fead', '34185817-e72e-418a-857f-6c6ebfc862b8', 1, 'Only the cesarean section procedure code is used, with no diagnosis code at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96a636ee-93f4-40fe-bebb-de5ea82e9434', '34185817-e72e-418a-857f-6c6ebfc862b8', 2, 'The newborn''s codes are assigned on the mother''s record instead of the mother''s own diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2121cb8-186e-47ba-a5d9-663066142de7', '34185817-e72e-418a-857f-6c6ebfc862b8', 3, 'Preeclampsia is never coded when a cesarean section is performed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34ccca79-3c6f-4a50-9639-5caec69a6013', '5eb2a33c-98af-4743-b6d3-43db5b1b1718', 0, 'A code reflecting liveborn infant according to place of birth/type of delivery (from the Z38 category), since this is the standard principal diagnosis for a healthy newborn''s own birth record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6d91c59-fb98-4e1d-8efa-2073512bc8a6', '5eb2a33c-98af-4743-b6d3-43db5b1b1718', 1, 'The same principal diagnosis code used on the mother''s obstetric record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b21a1f95-f193-479a-855a-48b0950c072e', '5eb2a33c-98af-4743-b6d3-43db5b1b1718', 2, 'No code is ever assigned on a newborn''s own record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ce10be0-584f-4698-b573-dbb9cdd89475', '5eb2a33c-98af-4743-b6d3-43db5b1b1718', 3, 'A code for prematurity, regardless of gestational age');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5053f64d-a596-4b2e-ac08-c597ef703988', 'a5d59ca6-787c-4272-b994-ed3648ff4e4d', 0, 'Gestational age is never separately coded on a newborn''s record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('863d954f-b79b-4e51-99fa-39ce592ba8e8', 'a5d59ca6-787c-4272-b994-ed3648ff4e4d', 1, 'A specific code reflecting the newborn''s gestational age (in completed weeks) should be assigned in addition to any other applicable newborn diagnosis codes, since ICD-10-CM includes specific codes for extreme immaturity/preterm newborns by gestational age');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66fcba96-3b65-40f2-ac37-fe2071b02591', 'a5d59ca6-787c-4272-b994-ed3648ff4e4d', 2, 'Gestational age is coded only if the infant requires NICU admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb511654-0886-4db8-833e-9b4e22f4f8df', 'a5d59ca6-787c-4272-b994-ed3648ff4e4d', 3, 'Gestational age coding applies only to infants born after 40 weeks');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53994656-2e65-4ec7-bcc4-0fd847b3dfe8', '7a003a82-1af4-4eae-bdb9-eead6862f5a8', 0, 'ICD-10-CM provides combination codes capturing the substance use disorder (e.g., mild, moderate, severe alcohol use disorder) together with associated states like intoxication, withdrawal, or substance-induced conditions, when documented, similar in structural concept to the diabetes/manifestation combination coding already covered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('487247ec-ff2b-4ee6-8035-d6c2875aee5d', '7a003a82-1af4-4eae-bdb9-eead6862f5a8', 1, 'Substance use disorders and intoxication/withdrawal are always coded as entirely unrelated conditions with no combination logic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5708cbe8-331f-4377-9f84-6cdb698d163b', '7a003a82-1af4-4eae-bdb9-eead6862f5a8', 2, 'Only the withdrawal state is ever coded; the underlying use disorder is never separately captured');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32abec2c-b352-49cd-8db7-9f88a94e9337', '7a003a82-1af4-4eae-bdb9-eead6862f5a8', 3, 'Substance use disorder severity (mild/moderate/severe) is never a coding element');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c235a5e9-d4bb-4bc1-9011-a2848934c0d5', 'f26bd671-6bb5-4cc8-8b48-c4440c3a1fa1', 0, 'ICD-10-CM still uses ''abuse'' and ''dependence'' as its primary severity terms, identical to DSM-IV');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85d406d7-e75c-4d43-a0cb-28e27a3b98f8', 'f26bd671-6bb5-4cc8-8b48-c4440c3a1fa1', 1, 'Current ICD-10-CM substance use disorder codes are generally structured around a severity spectrum (e.g., mild, moderate, severe use disorder), which aligns more closely with DSM-5''s unified ''use disorder'' severity model rather than the older DSM-IV abuse/dependence dichotomy — though ''abuse'' still appears as a term within some ICD-10-CM code descriptors for certain substances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ad8a0a5-6d94-46d8-a887-86fe00cd632e', 'f26bd671-6bb5-4cc8-8b48-c4440c3a1fa1', 2, 'Abuse and dependence are no longer codeable under ICD-10-CM at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d579b4c5-14ce-487e-ae89-931c56eb9a9f', 'f26bd671-6bb5-4cc8-8b48-c4440c3a1fa1', 3, 'The abuse/dependence distinction applies only to opioids, not other substances');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bad21fe4-a945-4a71-ab10-e997b9840c66', 'c9c152c9-39af-4039-8b44-8632d73085de', 0, 'A code capturing the specific episode type (recurrent), severity/course if documented, and current remission status, since ICD-10-CM''s mood disorder codes are structured to capture these clinically significant distinctions rather than a single generic ''depression'' code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3bd545c-ec8f-44cb-b19a-855e247bc70e', 'c9c152c9-39af-4039-8b44-8632d73085de', 1, 'Only a generic ''depression, unspecified'' code regardless of the specificity documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('886e525c-05c1-4d79-9ff7-9d9583fa7999', 'c9c152c9-39af-4039-8b44-8632d73085de', 2, 'Remission status is never a coding element for depressive disorders');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f371b0a-5f19-4710-a126-a0ef6dfbdb9d', 'c9c152c9-39af-4039-8b44-8632d73085de', 3, 'Recurrent vs. single-episode is never distinguished in ICD-10-CM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('385eac22-30d6-45df-8cfd-e899e211728b', 'b0c7d0e1-fc1b-4248-9a38-1cb3943dc4aa', 0, 'Only one of the two conditions may ever be coded, whichever is more severe');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('efb17e2f-a52e-4995-bab1-f074a25812e8', 'b0c7d0e1-fc1b-4248-9a38-1cb3943dc4aa', 1, 'Both conditions are coded, each per their own respective specific ICD-10-CM code/guideline, as co-occurring diagnoses when both are clinically addressed during the stay — there is no rule requiring only one behavioral health diagnosis per encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba6e9b25-4324-47ca-b3d6-18036b51b40e', 'b0c7d0e1-fc1b-4248-9a38-1cb3943dc4aa', 2, 'The two conditions must always be combined into a single ''dual diagnosis'' code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09485edb-b2f9-45ac-97d3-782d4df82813', 'b0c7d0e1-fc1b-4248-9a38-1cb3943dc4aa', 3, 'Substance use disorders can never be coded alongside a primary psychiatric diagnosis');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35597508-b3a8-4e60-b974-b9636a6669b2', 'f555b57c-4079-4ab6-bfbc-6caa2efd98ea', 0, 'The 7th character ''D'' with a delayed-healing designation (where the specific code structure provides for it) reflects a subsequent encounter where healing is not proceeding as typically expected, distinct from routine subsequent care (''D'' without delayed-healing distinction) or the initial encounter (''A'')');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8dbf708d-c73f-4296-8f8f-0d88728d0680', 'f555b57c-4079-4ab6-bfbc-6caa2efd98ea', 1, 'Delayed healing is never captured within the 7th character system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbe09be2-950d-4b65-abe6-f823ef70d463', 'f555b57c-4079-4ab6-bfbc-6caa2efd98ea', 2, 'All subsequent encounters are coded identically regardless of healing status');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('294cc4d8-4c0e-4814-84eb-4322d1630666', 'f555b57c-4079-4ab6-bfbc-6caa2efd98ea', 3, 'The 7th character extension system doesn''t apply to fracture codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c72eede-02b0-4f9b-b0c3-c4a13a0062a4', '18184aa3-fac0-42fa-b6f7-38112f5ec525', 0, 'A specific 7th character extension exists (where the fracture code category provides for it) reflecting subsequent care for a fracture with nonunion, distinct from routine healing or delayed healing/malunion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('697a7a8d-c435-442f-958c-614470945a2d', '18184aa3-fac0-42fa-b6f7-38112f5ec525', 1, 'Nonunion is never a distinct coding concept from routine healing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e41f170-04f6-40ab-8b06-09286ca6b6d9', '18184aa3-fac0-42fa-b6f7-38112f5ec525', 2, 'Nonunion fractures are coded using the same 7th character as an initial encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf96d0f8-cac7-4a8e-81f6-625da461665d', '18184aa3-fac0-42fa-b6f7-38112f5ec525', 3, 'Nonunion can only be coded for open fractures, never closed fractures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5621125-80cb-41bf-a653-7b81fe565fa1', 'de4123e9-e142-481d-a045-e79fd846552a', 0, 'The injury listed first alphabetically is always the principal diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9ccbfe9-77ec-486d-8288-7ed32a255290', 'de4123e9-e142-481d-a045-e79fd846552a', 1, 'Selection follows the same general UHDDS principal-diagnosis principle applied to trauma: the condition established after study as chiefly responsible for the admission, which in a multi-trauma case often (though not automatically) reflects the most severe/resource-intensive injury, but should be determined by actual clinical circumstances of the admission, not a fixed rule of thumb');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1414348-8545-4406-896b-f0729f860ffc', 'de4123e9-e142-481d-a045-e79fd846552a', 2, 'Only one injury from a multi-trauma presentation may ever be coded; the others are always dropped');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da23b5e6-bd7f-478f-95e6-3486581ee3ae', 'de4123e9-e142-481d-a045-e79fd846552a', 3, 'The injury requiring surgery is always automatically the principal diagnosis regardless of other clinical factors');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('946565dc-b974-40eb-bcd1-72864020be6f', 'b7178cb2-cff2-462f-95e6-516e34270ffc', 0, 'A single code always covers any number of fractures regardless of how many bones are involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04514e0d-96a6-4124-a7ea-1b2d8da9532a', 'b7178cb2-cff2-462f-95e6-516e34270ffc', 1, 'Fractures of different bones generally each require their own separate code (per the specific fracture site), while multiple fracture sites within specific single-bone categories may sometimes have combination-style guidance depending on the specific code category''s structure — coders should check the specific fracture category''s own conventions rather than assuming a blanket rule');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0a4012e-8b95-42fa-9480-580613baac23', 'b7178cb2-cff2-462f-95e6-516e34270ffc', 2, 'Only the most proximal fracture is ever coded when multiple fractures occur');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d734e08-3ab3-48ad-bcc8-b56c23f40bdb', 'b7178cb2-cff2-462f-95e6-516e34270ffc', 3, 'Fracture coding never depends on which specific bone(s) are involved');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46ec33cb-ace9-4001-898d-6fc1dd789d30', 'c6d73230-7c31-4f73-b9d2-3f0609dfa414', 0, 'Open versus closed status has no bearing on ICD-10-CM fracture code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e21dbb22-8a97-41b0-ac04-a43f9cc19c8f', 'c6d73230-7c31-4f73-b9d2-3f0609dfa414', 1, 'Many fracture codes are structured with distinct code options for open versus closed fractures (and further, by open fracture classification type, e.g., Gustilo type, for certain sites), meaning this documented detail directly affects correct code assignment, not merely severity description');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b51c9672-5421-482c-bea6-96c22474055d', 'c6d73230-7c31-4f73-b9d2-3f0609dfa414', 2, 'Open fractures are always coded as more severe injuries using trauma codes unrelated to the fracture chapter entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df3a9e01-5d5d-43d6-b0e5-aedc5e9f619e', 'c6d73230-7c31-4f73-b9d2-3f0609dfa414', 3, 'Closed fractures are never separately identified from soft tissue injuries');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd3f16c0-cf8f-4e51-969f-5e105dc123d7', '42f2d974-3d63-4e9d-ae3d-bfacf5c8e626', 0, 'External cause codes (capturing the intent — accidental, self-harm, assault, undetermined — and mechanism/place of injury) provide important supplemental data about how and why the injury occurred, reported alongside (never instead of) the actual injury diagnosis code(s)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1acd8cfc-2043-4135-96e9-5585acb5d84b', '42f2d974-3d63-4e9d-ae3d-bfacf5c8e626', 1, 'Assault-related injuries can never be coded using external cause codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57995511-2150-46ad-928c-5be9df41a1d8', '42f2d974-3d63-4e9d-ae3d-bfacf5c8e626', 2, 'External cause coding replaces the need to code the actual physical injury');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('536a09e2-905e-4207-9026-83741124d7a9', '42f2d974-3d63-4e9d-ae3d-bfacf5c8e626', 3, 'Intent (accidental vs. assault vs. self-harm) is never distinguished in ICD-10-CM external cause codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfb5cb99-0d7b-473a-b6a4-4a57042a072a', '057b514e-2778-4bfd-a214-475cc84c850f', 0, 'The actual physical injury/condition is coded first, with an external cause code reflecting intentional self-harm reported as supplemental data, plus any applicable underlying psychiatric diagnosis coded per its own guidelines if addressed during the encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f3be55e-ac59-4a4c-9a33-275fb64f0a0b', '057b514e-2778-4bfd-a214-475cc84c850f', 1, 'Only a psychiatric diagnosis code is ever used; the physical injury is never separately coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3681f64f-6c98-4dfa-8ddf-273951a9dce5', '057b514e-2778-4bfd-a214-475cc84c850f', 2, 'Self-harm intent can never be coded in ICD-10-CM external cause codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f520206b-bae2-479a-8817-ae9033eb61c5', '057b514e-2778-4bfd-a214-475cc84c850f', 3, 'The injury and the self-harm intent are always combined into a single code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0040f6d7-b78b-4616-a6df-2ca8c4b36fba', 'b637e117-e3d7-4cd4-ac42-fe1374e55f89', 0, 'An adverse effect is a reaction to a drug correctly prescribed and properly administered (coded via the specific condition plus an adverse-effect-of-drug code), while a poisoning involves incorrect use (overdose, wrong drug/route, non-prescribed use, or intentional misuse) — these represent distinct coding scenarios with different code structures/sequencing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1aec71b8-9ac0-4b2b-a2c9-e7bef6fcc7fd', 'b637e117-e3d7-4cd4-ac42-fe1374e55f89', 1, 'Adverse effect and poisoning are coded identically with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9788a8c6-b618-416c-a5de-136ce6afceda', 'b637e117-e3d7-4cd4-ac42-fe1374e55f89', 2, 'Poisoning applies only to illegal drugs, never prescription medications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('214b2242-e01c-4ef8-bfbf-d68afd2b36a8', 'b637e117-e3d7-4cd4-ac42-fe1374e55f89', 3, 'Adverse effect coding is never used for properly prescribed medications');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5cb2cf32-0d39-4c53-be50-c6549df90e91', '50c27731-b322-4d1e-b93a-453996a1f01d', 0, 'The poisoning code is sequenced first, followed by code(s) for the specific manifestation/effect (e.g., respiratory depression, altered consciousness) and an external cause code reflecting intent (accidental, in this example)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e01ea04-07d4-4ca8-aab8-158292c608b2', '50c27731-b322-4d1e-b93a-453996a1f01d', 1, 'Only the manifestation is coded; the poisoning itself is never separately coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f7e8a7d-ac1e-4de4-b08c-d7be5ec07b83', '50c27731-b322-4d1e-b93a-453996a1f01d', 2, 'The poisoning code and manifestation code are never both reported for the same encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4275494b-7acd-4de0-ae88-969e08ae7276', '50c27731-b322-4d1e-b93a-453996a1f01d', 3, 'External cause/intent is never coded for poisoning cases');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2fb8fb1e-b934-42e9-b7dc-653b17bc086c', 'd608c2eb-85bf-47ab-960b-9a9bb90d0592', 0, 'The manifestation/condition (e.g., the rash) is coded first, followed by the appropriate adverse-effect-of-drug code identifying the causative substance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d6df175-a2a9-4bd5-a6bc-f1cb1fea74f4', 'd608c2eb-85bf-47ab-960b-9a9bb90d0592', 1, 'The adverse-effect-of-drug code is always sequenced first, before the manifestation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2303ba70-568e-469b-ac56-dd5f9d081990', 'd608c2eb-85bf-47ab-960b-9a9bb90d0592', 2, 'Adverse effects from properly prescribed medications are never coded at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('293a0448-91a4-4cb4-bd47-3cdd8f8e3ffe', 'd608c2eb-85bf-47ab-960b-9a9bb90d0592', 3, 'Only a poisoning code applies, regardless of correct prescription/administration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25bbf81a-a4c2-4ea8-9ec2-9a64106ae95a', '998e25b0-30cb-4dce-8306-1b458d7f44b0', 0, 'ECT has its own specific ICD-10-PCS code(s) within the Mental Health/related sections reflecting this specific therapeutic modality, distinct from general Medical and Surgical section root operations used for physical procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc308f9b-5e3e-41ad-a6d0-e845c17f33dc', '998e25b0-30cb-4dce-8306-1b458d7f44b0', 1, 'ECT is coded using the same root operation as a surgical brain biopsy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81da6684-6f52-4d55-8cf4-a45c9c583649', '998e25b0-30cb-4dce-8306-1b458d7f44b0', 2, 'ECT is never separately coded in ICD-10-PCS');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c59f363-34f4-46fd-8a1d-416b137c9bc8', '998e25b0-30cb-4dce-8306-1b458d7f44b0', 3, 'ECT is coded exclusively using CPT, never ICD-10-PCS, even in the inpatient setting');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f818482f-87d3-458a-a81b-127962fbfbd8', '7858e061-fed9-4df4-906f-1c2e18f41f1a', 0, 'A code for gestational diabetes, since any diabetes during pregnancy is classified as gestational');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6cc02af-f429-40ae-86ea-86eb9966227e', '7858e061-fed9-4df4-906f-1c2e18f41f1a', 1, 'A specific code for pre-existing (pregestational) diabetes complicating pregnancy, distinct from gestational diabetes, since ICD-10-CM classifies these as different conditions based on whether the diabetes predated the pregnancy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09e69be8-8c0f-4cf8-bb11-6748cfe90c27', '7858e061-fed9-4df4-906f-1c2e18f41f1a', 2, 'The same code used for gestational diabetes, since ICD-10-CM makes no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e9d2090-b76a-40ee-ae8b-076ea8253bc5', '7858e061-fed9-4df4-906f-1c2e18f41f1a', 3, 'No diabetes code is used during pregnancy under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae5a68df-d0a4-4ed8-b062-241fc41da9db', 'e06d23a8-e65c-4488-9d0f-12fd97233243', 0, 'A code for preterm labor without delivery, reflecting the actual reason for this admission, since delivery did not occur during this specific encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dda3d27d-2510-4080-b817-9bc406b18a1a', 'e06d23a8-e65c-4488-9d0f-12fd97233243', 1, 'An outcome-of-delivery code, since the patient was pregnant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e2e5fbe-326d-4dda-9e0c-657520932005', 'e06d23a8-e65c-4488-9d0f-12fd97233243', 2, 'A code for full-term delivery, since delivery will eventually occur');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d6a290c-58bd-46d2-b40a-714df87be1a1', 'e06d23a8-e65c-4488-9d0f-12fd97233243', 3, 'No code can be assigned since delivery didn''t occur');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77b1434b-97bf-4f62-a450-eaa613c1fe14', '80420a65-017b-4551-8ff1-616de2919495', 0, 'Used for routine antepartum/prenatal visits where no current complication is the focus of the encounter, reflecting normal pregnancy supervision, as distinguished from encounters where an actual pregnancy complication is being addressed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47380a60-8cbe-4ecd-9da1-4157a7c4afba', '80420a65-017b-4551-8ff1-616de2919495', 1, 'Used only for high-risk pregnancies with active complications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8809f01-cf18-4ac9-9f07-b63991c456c1', '80420a65-017b-4551-8ff1-616de2919495', 2, 'Used interchangeably with the outcome-of-delivery codes for every prenatal visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b72dba5f-04a7-47f3-a02b-80efa74437fd', '80420a65-017b-4551-8ff1-616de2919495', 3, 'Never used once a patient reaches the third trimester');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e963cf9d-7a0e-41ba-9595-7d6c6e49d175', '29995c34-bd2a-41ee-af50-b363adf38c1e', 0, 'A specific code reflecting pregnancy management/delivery affected by a history of previous cesarean delivery, since this is a recognized specific obstetric coding category distinct from a generic ''complication of pregnancy'' code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa743382-4d67-4631-8772-184169f6abef', '29995c34-bd2a-41ee-af50-b363adf38c1e', 1, 'No code is needed for the indication; only the delivery outcome code is used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82ba5393-b596-498e-b463-becb3532abdf', '29995c34-bd2a-41ee-af50-b363adf38c1e', 2, 'The same code used for a first-time cesarean with no prior history');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dae15252-e2bb-4ea1-b471-79c552c103c9', '29995c34-bd2a-41ee-af50-b363adf38c1e', 3, 'A code indicating fetal distress, regardless of whether fetal distress was actually present');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8a5e770-b79e-4354-ad22-f9e85f6ed873', '3efe8ecb-757a-40f9-832f-1b248a57f15e', 0, 'TTN is coded using the same code as respiratory distress syndrome of the newborn, since both involve respiratory difficulty');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc5ccf13-5fc6-4b7e-87ca-6ffbdd6984ef', '3efe8ecb-757a-40f9-832f-1b248a57f15e', 1, 'TTN has its own specific ICD-10-CM code, distinct from respiratory distress syndrome of the newborn (RDS) and other neonatal respiratory conditions, reflecting its own distinct clinical entity and expected transient course');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('33914208-49e2-4ce8-9f7f-37f378480834', '3efe8ecb-757a-40f9-832f-1b248a57f15e', 2, 'TTN is never separately coded; only the respiratory support procedure is coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0c09746-8f9a-4994-a320-4329a1bb2f31', '3efe8ecb-757a-40f9-832f-1b248a57f15e', 3, 'TTN can only be coded if the newborn requires mechanical ventilation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfb64cb8-1b44-40d4-a96c-f4336bd5b523', '9a2de761-28e5-4cbe-a6bf-78b32c91a7bf', 0, 'A specific ICD-10-CM code exists for neonatal withdrawal symptoms from maternal drug use (neonatal abstinence syndrome), reported on the newborn''s own record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4dffccb0-9712-4529-8377-3b68ab5c5b5a', '9a2de761-28e5-4cbe-a6bf-78b32c91a7bf', 1, 'NAS is coded identically to a newborn drug poisoning code, with no distinction from an accidental ingestion scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d582df5-8a7d-4103-b3b4-9c733caf02bf', '9a2de761-28e5-4cbe-a6bf-78b32c91a7bf', 2, 'NAS is never coded since it results from maternal (not the newborn''s own) substance use');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0df016ec-98e9-4160-8e5c-750dccf38476', '9a2de761-28e5-4cbe-a6bf-78b32c91a7bf', 3, 'NAS is coded only on the mother''s record, never the newborn''s own record');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db2ceead-c559-4200-b8bf-06714d66c39d', 'a873844a-e8ea-462c-b35d-e51545e9d27f', 0, 'The mother''s own substance use disorder is coded on the MOTHER''s record (per standard substance use disorder coding), while any resulting effects on the newborn (e.g., NAS) are coded on the NEWBORN''s own separate record — these are coded on their respective, distinct patient records, not combined onto one chart');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97e9063a-f52e-4796-b78d-07c5626a5bb3', 'a873844a-e8ea-462c-b35d-e51545e9d27f', 1, 'Only the newborn''s record captures any of this information; the mother''s record has no substance use disorder code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5dfdd6f-8118-41ef-9312-2bb12936aa97', 'a873844a-e8ea-462c-b35d-e51545e9d27f', 2, 'The mother and newborn share a single combined coding record for this scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('49ba4551-b591-4118-b8b9-cfe17460de52', 'a873844a-e8ea-462c-b35d-e51545e9d27f', 3, 'Maternal substance use disorder during pregnancy is never coded under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb07d0f4-58fd-48c4-b9c7-8ece00d4b5f0', '7bee66b9-9eff-4bf4-b19d-7a17ba3a288a', 0, 'Only one of the two diagnoses, whichever the coder judges more clinically significant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdf8082d-1ec1-45e2-8bb6-c60c21b71d3f', '7bee66b9-9eff-4bf4-b19d-7a17ba3a288a', 1, 'Both conditions, each per their own specific ICD-10-CM code, since both are distinct, actively-treated diagnoses meeting the additional-diagnosis reporting criteria');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5453e0e6-1054-4572-8267-3b9c656bddda', '7bee66b9-9eff-4bf4-b19d-7a17ba3a288a', 2, 'A single combined ''anxiety spectrum'' code covering both conditions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95ab3220-14fa-47ee-b581-ecef8f621493', '7bee66b9-9eff-4bf4-b19d-7a17ba3a288a', 3, 'Panic disorder is never separately coded from generalized anxiety disorder');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7c58e4a-53d3-4dc5-8746-82f6f07691a9', '444f5b7c-94fb-45cb-a665-c81bdf2696c0', 0, 'Eating disorders have their own specific, distinct ICD-10-CM codes reflecting the specific disorder type, structurally separate from the general mood/anxiety disorder code categories');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cdb7601a-dd6a-497b-9f2a-f91672622d99', '444f5b7c-94fb-45cb-a665-c81bdf2696c0', 1, 'Eating disorders are coded using the same codes as generalized malnutrition, with no distinct classification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f791480f-2826-4005-9796-20bce1197b96', '444f5b7c-94fb-45cb-a665-c81bdf2696c0', 2, 'Eating disorders are never separately identified in ICD-10-CM');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6482ab0f-8209-4507-857d-eff333956358', '444f5b7c-94fb-45cb-a665-c81bdf2696c0', 3, 'Only anorexia nervosa has a specific code; bulimia nervosa has no corresponding code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('524cf958-3a61-46b0-b38d-930242e54a2c', '576e830b-2b6e-42bb-9df4-5a094113a874', 0, 'Always coding PTSD regardless of whether it was addressed this admission, since it is a serious chronic condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca3b8564-4be8-47a3-8f58-bf7ab61bd0e4', '576e830b-2b6e-42bb-9df4-5a094113a874', 1, 'Applying the same UHDDS additional-diagnosis test used throughout Domain 1 — if PTSD is not clinically evaluated, treated, monitored, or otherwise impactful to THIS specific admission, it would not automatically qualify as a reportable additional diagnosis for this encounter, regardless of its overall clinical significance to the patient generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d5154a6-4087-42e3-abb5-00bb2a5e9046', '576e830b-2b6e-42bb-9df4-5a094113a874', 2, 'Never coding PTSD under any circumstance in an inpatient setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4210455-6c0b-468a-a74e-292f6412c467', '576e830b-2b6e-42bb-9df4-5a094113a874', 3, 'Coding PTSD only if the patient''s admission is to a psychiatric unit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffc74fa6-57b5-4f34-9bc5-2ce15f57e1dc', 'bc54b25a-8897-4396-a95b-1d977e7f082e', 0, 'A code capturing the opioid use disorder with the appropriate remission status, plus, where applicable, a code/notation reflecting the therapeutic use of methadone for maintenance therapy (as clinically distinct from an active, untreated use disorder)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16ae0958-6724-45f5-befa-d98d3b71273b', 'bc54b25a-8897-4396-a95b-1d977e7f082e', 1, 'Methadone maintenance patients are always coded as if they have an active, unremitted use disorder regardless of documented remission status');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad0efd9a-ce2c-4b64-8098-c0f8ffe1cc5d', 'bc54b25a-8897-4396-a95b-1d977e7f082e', 2, 'Remission status is never a coding element for opioid use disorder');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18fe51fe-a715-4809-a71b-234c0252b668', 'bc54b25a-8897-4396-a95b-1d977e7f082e', 3, 'Methadone maintenance therapy is never separately reflected in ICD-10-CM coding in any way');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81fce221-b17b-4ae4-bd93-5bd8914c0ffe', 'e1308c02-c9c4-4597-bcc7-4b99afe4960b', 0, 'LOC duration has no bearing on ICD-10-CM TBI code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a558935a-fcd2-4d94-a26d-ea449d5d7f04', 'e1308c02-c9c4-4597-bcc7-4b99afe4960b', 1, 'Many traumatic brain injury codes are structured with distinct options based on documented loss of consciousness duration/severity (e.g., with loss of consciousness of specified duration, without loss of consciousness, with loss of consciousness of unspecified duration), meaning this documented detail directly affects correct code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e04f938-ab02-4647-8718-dbccb82d3b20', 'e1308c02-c9c4-4597-bcc7-4b99afe4960b', 2, 'LOC duration is relevant only to Glasgow Coma Scale coding, never TBI diagnosis coding itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('000e50f8-0b5f-435d-8a28-8c6dbf5a81ac', 'e1308c02-c9c4-4597-bcc7-4b99afe4960b', 3, 'TBI codes never distinguish by LOC status at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14e78862-e79f-4778-bf25-348b5c035916', '91728ad3-fa15-4c0a-87f4-0240f8f5051e', 0, 'ICD-10-CM includes specific codes allowing the GCS score (eye, verbal, and motor response components) to be separately coded when documented, supplementing the primary TBI diagnosis code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03732bb1-5a0c-47db-ba27-f2cd1ef61445', '91728ad3-fa15-4c0a-87f4-0240f8f5051e', 1, 'GCS is never separately coded in ICD-10-CM under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad226cf1-5c61-42d1-b537-65f060d89454', '91728ad3-fa15-4c0a-87f4-0240f8f5051e', 2, 'GCS coding replaces the need for a specific TBI diagnosis code entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0722a798-8b0c-4df7-9e96-e15d4483b919', '91728ad3-fa15-4c0a-87f4-0240f8f5051e', 3, 'GCS codes apply only to non-traumatic causes of altered consciousness, never TBI');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac9e2aff-98f8-42f0-878f-5d1c0df7d42c', '2529beb3-8f10-4e9b-a54d-e81588036ea9', 0, 'The root operation Extirpation (taking out solid matter — the clotted blood/hematoma — that has no natural or created channel to the outside of the body) most likely applies to evacuating the hematoma itself, following the craniotomy approach used to access it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c00849bd-3560-45ec-86c9-48a1d44fb143', '2529beb3-8f10-4e9b-a54d-e81588036ea9', 1, 'The root operation Drainage always applies to any hematoma evacuation regardless of whether the blood has clotted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e1d6187-1d21-49ef-8743-92d1889be0c4', '2529beb3-8f10-4e9b-a54d-e81588036ea9', 2, 'Hematoma evacuation is never separately coded from the craniotomy approach itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73fd95db-12bc-4622-997c-1597a8e2f39d', '2529beb3-8f10-4e9b-a54d-e81588036ea9', 3, 'The root operation Repair is used for any hematoma evacuation regardless of clinical specifics');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('929f4c5e-333c-48fa-96e5-024f6002be1a', '1e4668af-8a41-48ce-9393-728c988b140c', 0, 'TBSA percentage has no bearing on ICD-10-CM burn coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ae6eb04-e8ce-45aa-8db5-f5e716487bfe', '1e4668af-8a41-48ce-9393-728c988b140c', 1, 'ICD-10-CM includes specific codes for reporting the extent of body surface involved (TBSA) and the percentage with third-degree burns specifically, supplementing the primary burn-site/degree codes — a documented TBSA percentage directly supports assigning these supplemental codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4169f5d0-4cac-45f6-aab7-51b5787b9a55', '1e4668af-8a41-48ce-9393-728c988b140c', 2, 'Only first-degree burns require TBSA documentation; deeper burns never do');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('727e351f-ab29-4ba9-9693-9737976e93e9', '1e4668af-8a41-48ce-9393-728c988b140c', 3, 'TBSA is coded using the same codes as the specific burn site, with no separate code category');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d99bef2-d8e4-4648-a33d-60b667539c3d', '4e92f31b-60a7-4919-aad2-e563e89cb32e', 0, 'The burn of the highest degree (most severe) is generally sequenced first among the various burn sites, per the burn coding guideline''s sequencing hierarchy, when multiple burn sites/degrees are present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca9db45a-880e-47df-8634-ff7853ef98c2', '4e92f31b-60a7-4919-aad2-e563e89cb32e', 1, 'Burns are always sequenced in the order the body sites are listed alphabetically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66f24790-bb69-43a3-8ce4-ca16d606bb62', '4e92f31b-60a7-4919-aad2-e563e89cb32e', 2, 'Only the largest-surface-area burn site is ever coded; smaller sites are disregarded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd3e4475-669f-403d-9f8d-85fe6638151d', '4e92f31b-60a7-4919-aad2-e563e89cb32e', 3, 'All burns are combined into a single generic ''multiple burns'' code with no site/degree detail');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06f240ba-5a80-405c-ac8f-6aee0a56fb24', '7461c7bd-586d-4088-8f93-0d3ff91a8638', 0, 'Transplantation, with a qualifier value reflecting the donor-source relationship (e.g., allogeneic, from an unrelated donor)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61e79d35-fe31-42f2-883d-64b4a99135d2', '7461c7bd-586d-4088-8f93-0d3ff91a8638', 1, 'Replacement, since marrow is being physically replaced');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2092fe5-80c8-49ad-9129-3fac963392a2', '7461c7bd-586d-4088-8f93-0d3ff91a8638', 2, 'Insertion, since cells are being placed into the body');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1dfe1417-119e-44a0-b7c3-7b14e868dfe4', '7461c7bd-586d-4088-8f93-0d3ff91a8638', 3, 'Supplement, since the goal is to reinforce marrow function');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9ade9d5-d8e2-449e-b5e4-ccf1dac2aa93', '4070c650-2290-4a5e-82eb-38c2f61c8fb2', 0, 'The chemotherapy administration encounter is coded per the appropriate encounter-for-chemotherapy Z code (with the malignancy as an additional diagnosis, per the earlier neoplasm sequencing rule), without re-coding the port placement procedure, since that device was placed during a prior, separate encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88c0e061-4c1e-40a5-bfd1-6e81a9cf35eb', '4070c650-2290-4a5e-82eb-38c2f61c8fb2', 1, 'The port placement procedure must be re-coded at every single chemotherapy administration encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f051979-3098-42ba-9710-dc85e57ce081', '4070c650-2290-4a5e-82eb-38c2f61c8fb2', 2, 'Chemotherapy administered via a port is coded completely differently from chemotherapy administered via peripheral IV, using an entirely separate diagnosis-code structure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba42ef4f-bdeb-4cb0-922f-e65c2f42d7e8', '4070c650-2290-4a5e-82eb-38c2f61c8fb2', 3, 'No diagnosis code is needed for a chemotherapy administration encounter');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('41c466c8-5d9e-44ef-8376-940906722063', '81d5ac2a-b357-4306-8526-99ba3717f3ac', 0, 'Each individual radiation fraction/session administered during the inpatient stay would generally be coded per the applicable ICD-10-PCS radiation oncology code(s) for the sessions actually delivered during that stay, in addition to appropriately coding the reason for the inpatient admission itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a82a1bb8-eb0f-4287-9bbf-ea87efddbc3f', '81d5ac2a-b357-4306-8526-99ba3717f3ac', 1, 'Radiation therapy can never be coded during an inpatient stay under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf52afee-46fc-4781-a0a1-96caa78ed593', '81d5ac2a-b357-4306-8526-99ba3717f3ac', 2, 'Only one radiation code is ever used regardless of how many fractions were delivered during the stay');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c7a40b5-e825-4a4a-aaba-3f40f189dc55', '81d5ac2a-b357-4306-8526-99ba3717f3ac', 3, 'Radiation therapy sessions are automatically bundled into the unrelated admission''s principal procedure with no separate coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ad9e35d-e987-444d-8ddd-1608acd89cfb', '1bd59569-fe4d-491c-bc39-2d42df6eb7e8', 0, 'A code reflecting the genetic susceptibility/family history (as applicable) supports the medical necessity for prophylactic surgery, coded alongside the appropriate ICD-10-PCS procedure code(s) for the bilateral mastectomy — since no active malignancy exists, an active cancer code is not used as the reason for this procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5dc94f50-3324-4479-9bc5-aa0c988fe86c', '1bd59569-fe4d-491c-bc39-2d42df6eb7e8', 1, 'The active malignant neoplasm code is always used regardless of whether cancer is actually present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81d54fd5-cecc-413a-b238-d5df29fa8e3c', '1bd59569-fe4d-491c-bc39-2d42df6eb7e8', 2, 'Prophylactic mastectomy can never be coded since no disease is being treated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a58063a-4d52-4966-8795-8e1db16c409d', '1bd59569-fe4d-491c-bc39-2d42df6eb7e8', 3, 'Genetic mutation status is never a coding consideration for surgical procedures');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9e809d0b-3652-42e1-9954-6df76bfe5b45', '9ac3e01c-8e3a-4709-8609-492049e7794d', 0, 'Assuming single gestation and vaginal delivery by default without further review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48bc3967-8456-411c-9081-25860b7bcdc9', '9ac3e01c-8e3a-4709-8609-492049e7794d', 1, 'Reviewing the full labor and delivery record (nursing delivery note, operative report if applicable, newborn record) for the specific details needed (gestation number, delivery type, outcome) before finalizing the outcome-of-delivery code, since a vague summary statement doesn''t itself supply the required coding specificity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecde9a4e-eb8d-45e1-914a-445927b85c29', '9ac3e01c-8e3a-4709-8609-492049e7794d', 2, 'Coding is impossible without a query in 100% of such cases, even when other parts of the record supply the needed detail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf07b869-4d1c-42d0-94dc-20357add2922', '9ac3e01c-8e3a-4709-8609-492049e7794d', 3, 'Using the newborn''s own principal diagnosis code on the mother''s record instead of a proper outcome-of-delivery code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0acc39fd-a180-4bc3-ae07-7884dd4ada84', '98a72153-8e62-4845-9a14-cd280578ad7c', 0, 'Code only from the admission note, ignoring the more specific discharge summary language');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c789636f-e3ce-4f4e-8513-98814324e45b', '98a72153-8e62-4845-9a14-cd280578ad7c', 1, 'Recognize that later documentation in the same stay (the discharge summary) can supply greater specificity than an earlier, less detailed note, and review the full course of the stay for the most clinically accurate and complete picture before finalizing code specificity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8c639ac-474c-4da5-bb8a-e868c47499e7', '98a72153-8e62-4845-9a14-cd280578ad7c', 2, 'Query is always mandatory even when the discharge summary already supplies adequate specificity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3791616-4219-4e76-8f53-67556ca9bc98', '98a72153-8e62-4845-9a14-cd280578ad7c', 3, 'Use only the LEAST specific documentation found anywhere in the chart, by policy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54cfc6eb-0ad6-4840-9876-386a4854c889', '5b4d0e45-51ed-401f-8e4d-b6bac44eeb62', 0, 'Automatically apply the severity from six months ago to the CURRENT encounter without any current clinical reassessment, since it''s the same underlying condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d3c293f-5612-4fba-a154-f06c935fa83f', '5b4d0e45-51ed-401f-8e4d-b6bac44eeb62', 1, 'Recognize that substance use disorder severity can change over time (with treatment, relapse, etc.), so a prior encounter''s severity documentation doesn''t automatically apply to reflect the CURRENT clinical status — review current documentation for an updated assessment or query for current severity rather than assuming continuity from a prior encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62a0a1e9-b2b4-45f6-bbd2-dc1037ec725d', '5b4d0e45-51ed-401f-8e4d-b6bac44eeb62', 2, 'Never code alcohol use disorder if severity isn''t restated at every single encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0442f55-e60e-40c2-9c70-c0c5936d4b1c', '5b4d0e45-51ed-401f-8e4d-b6bac44eeb62', 3, 'Use the least severe classification by default whenever severity isn''t restated');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d0a52b06-150f-4adf-8588-6aedb3c924a4', 'decd8bef-97ff-4186-b24c-e092743118db', 0, 'Automatically use the ED triage note''s characterization without further review, since it was documented first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a665c50-914f-4bc6-9d43-b5e91b1f3f9d', 'decd8bef-97ff-4186-b24c-e092743118db', 1, 'Recognize this as a genuine documentation conflict regarding intent — review further clinical documentation for the physician''s own characterization, and query if the conflict remains unresolved and intent-specific coding accuracy is needed, since a triage note and an external police report may reflect different information sources with a genuine, unresolved discrepancy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9504385e-fe0a-45d4-9ded-2ac0d9d317c2', 'decd8bef-97ff-4186-b24c-e092743118db', 2, 'Always defer entirely to the police report over any clinical documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f259bf28-9695-4bd7-86d9-c19ea8260732', 'decd8bef-97ff-4186-b24c-e092743118db', 3, 'Refuse to code intent at all whenever any conflicting source exists anywhere in the chart');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37db16fe-f896-45cb-85f9-16396526e7c1', 'e59a9387-25d6-4127-b726-2cd9a63ce642', 0, 'Only one of the three sources may ever be used for coding, with the others disregarded entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48563b79-eedd-4c36-843b-dd2010635098', 'e59a9387-25d6-4127-b726-2cd9a63ce642', 1, 'Recognize that a newborn''s complete coding picture often legitimately draws from multiple qualified sources (nursing for certain structured data like Apgar scores, consistent with the same documentation-source exceptions discussed for BMI/wound staging; physicians for diagnoses), and reviewing the complete record across these sources — rather than assuming only a single note type is ever relevant — is appropriate for newborn coding specifically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1e9c72c-45c8-4b46-ab40-8bd2dc901a1d', 'e59a9387-25d6-4127-b726-2cd9a63ce642', 2, 'Newborn records may never combine nursing and physician documentation for coding purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ab79c79-e968-4527-b3d1-b2d864c14a72', 'e59a9387-25d6-4127-b726-2cd9a63ce642', 3, 'Gestational age can only ever be documented by a nurse, never a physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('beab8f37-409c-4afb-a656-9382dc84f3c0', 'd302f9c9-fa1e-4614-8b9a-48699a40999c', 0, 'Assume severe, active use disorder by default regardless of the positive treatment-response language');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ebf17f9-0e94-4edd-b439-6e32a6a69279', 'd302f9c9-fa1e-4614-8b9a-48699a40999c', 1, 'Recognize that ''doing well on treatment'' language, while clinically informative, doesn''t itself specify the formal severity/remission classification needed for the most specific code — review the full record for a more specific determination or query if genuinely needed, rather than assuming either severity level from general positive-progress language alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f9ce9f5a-7d05-403e-a7e2-8b2f31408de1', 'd302f9c9-fa1e-4614-8b9a-48699a40999c', 2, 'Code only the medication (buprenorphine/naloxone) with no underlying diagnosis at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5b3d3ea-823a-43d4-a1be-705106d8679d', 'd302f9c9-fa1e-4614-8b9a-48699a40999c', 3, 'Assume the condition is fully resolved and use no substance use disorder code at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a8fbc379-835f-4fe0-ac87-70a8f304dfb0', 'e75fd8b7-df6f-4941-abb6-cd7c5dee80e8', 0, 'Assume driver status by default for any motor vehicle collision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b196932f-76d0-4ae5-a951-c3f8f8871af9', 'e75fd8b7-df6f-4941-abb6-cd7c5dee80e8', 1, 'Review other documentation sources (EMS run sheet, ED triage note, additional H&P detail) that may supply the needed external-cause detail, since a brief H&P abbreviation alone often isn''t the only or most detailed source of injury-circumstance information in the record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6afc63b8-bd5d-48b6-9c0e-8cec222cbf01', 'e75fd8b7-df6f-4941-abb6-cd7c5dee80e8', 2, 'Skip external cause coding entirely whenever the H&P is brief');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1a994ec-6ca4-4351-9a5d-ba23cb54fca0', 'e75fd8b7-df6f-4941-abb6-cd7c5dee80e8', 3, 'Code the most severe possible external-cause scenario by default');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc25e171-775a-4a96-9a82-2f0da9c35b6b', 'aa2b0d2b-f2bc-4030-8fde-ad96c6d0e0ab', 0, 'TBSA percentage should be taken from whatever source states the highest number, regardless of clinical accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d500c176-4615-4c2d-8067-ac3ab56dafaf', 'aa2b0d2b-f2bc-4030-8fde-ad96c6d0e0ab', 1, 'TBSA percentage should be verified against the actual clinical documentation (e.g., a burn diagram/body chart, physician or burn-team assessment) specifically calculating that percentage, rather than assumed or estimated by the coder without a documented clinical basis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0277c588-dcfa-474c-9fe2-4cdcc1700118', 'aa2b0d2b-f2bc-4030-8fde-ad96c6d0e0ab', 2, 'TBSA percentage is a purely administrative data point requiring no clinical documentation support');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('891768e2-2506-46e1-9ad2-6fd7499bb8d4', 'aa2b0d2b-f2bc-4030-8fde-ad96c6d0e0ab', 3, 'TBSA is only relevant for coding when the patient is transferred to a burn center');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c467551-bb94-4c18-afc0-ba7cce403acc', '4c1ef0cd-f757-49e9-8000-c1e145757674', 0, 'Automatically use whichever gestational age results in the more specific/favorable code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e9b7b2b-b7ea-4031-bdfa-a04a130836d7', '4c1ef0cd-f757-49e9-8000-c1e145757674', 1, 'Recognize this as a documentation discrepancy warranting further review of the full prenatal record (e.g., dating based on LMP versus ultrasound dating conventions, which can legitimately differ) to determine the most clinically accurate current gestational age, querying if the discrepancy remains genuinely unresolved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d6ebc34-6cac-405a-a705-f80a9da1b1dc', '4c1ef0cd-f757-49e9-8000-c1e145757674', 2, 'Use only the ultrasound report, since imaging is always more accurate than a physician''s clinical note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82ef8ed1-bd1e-4c13-814e-04cbfa4cf9b2', '4c1ef0cd-f757-49e9-8000-c1e145757674', 3, 'Ignore gestational age entirely whenever any discrepancy exists');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e116cdfd-b855-4bd2-ad8b-947bb65efa35', 'c2794bf4-527f-4f80-8446-d34c8fdeace3', 0, 'Automatically add an anxiety disorder diagnosis based on the nursing assessment alone, without any physician documentation establishing that diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4449eff2-d55f-4e8b-973f-740bcc349f79', 'c2794bf4-527f-4f80-8446-d34c8fdeace3', 1, 'Recognize that nursing behavioral health assessments provide valuable clinical context but don''t themselves establish a distinct psychiatric diagnosis — if the nursing-documented symptom pattern suggests a possible additional diagnosis not addressed by the treating psychiatrist, this may represent a legitimate area for further chart review or query, not an automatic additional diagnosis based on nursing assessment alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('277753f4-bcd2-43ed-83a4-56a9d8389724', 'c2794bf4-527f-4f80-8446-d34c8fdeace3', 2, 'Ignore all nursing behavioral health documentation as categorically irrelevant to coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b847048-fb02-4849-bfcb-7f500d448535', 'c2794bf4-527f-4f80-8446-d34c8fdeace3', 3, 'Code only from the nursing assessment, disregarding the psychiatrist''s own diagnostic note');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f48d3b05-795f-4773-bafd-4055fad19b55', '5354a153-3a4a-4fec-9bde-454598a8a8c2', 0, 'Assume the surgery is being performed for an unrelated reason, since the surgeon''s own note doesn''t mention the genetic finding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cccde86e-3875-436c-90ef-199edfc00b39', '5354a153-3a4a-4fec-9bde-454598a8a8c2', 1, 'Recognize that the surgical encounter''s own documentation should itself reflect the indication for surgery (even if by appropriate cross-reference to the genetic counseling findings) to support accurate coding of that specific encounter — reviewing the surgeon''s full documentation (which may reference the genetic finding elsewhere, e.g., in a preop note) or querying if the connection is genuinely unclear from the surgical encounter''s own records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d4541a2-b2e1-441c-90e6-931439d4b1f6', '5354a153-3a4a-4fec-9bde-454598a8a8c2', 2, 'Automatically code an active malignancy as the indication regardless of what''s actually documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19bb7b81-278c-4b72-8efa-bbd10f2c4eec', '5354a153-3a4a-4fec-9bde-454598a8a8c2', 3, 'Ignore the genetic counseling note entirely since it wasn''t authored by the surgeon');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f27fd7b-f751-4f8c-ba77-6cd134ca70b8', '837d3b85-8746-4a70-ad03-70d695c91d5b', 0, 'Donor source is assumed based on the most common transplant type performed at that facility');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5007627-5c90-489b-871d-f1cd9c033e6d', '837d3b85-8746-4a70-ad03-70d695c91d5b', 1, 'The operative/procedure documentation should specifically establish the donor-source relationship, since this detail directly determines the correct ICD-10-PCS qualifier value — assuming a donor-source type without explicit documentation risks an inaccurate procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67e99ae4-d580-49fe-8dfd-3e6f58c70329', '837d3b85-8746-4a70-ad03-70d695c91d5b', 2, 'Donor source is never a documented or coded element for transplant procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8fb359c-6071-4a68-9b73-d7e97208b2de', '837d3b85-8746-4a70-ad03-70d695c91d5b', 3, 'Donor source only needs to be documented for pediatric transplant patients');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46436863-8c64-4cf8-bd7f-a392a222cbed', '91e5c9f2-f456-4906-8834-928896931964', 0, 'Assume the planning note''s total is what was delivered regardless of the actual delivery logs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0e70859-f635-4ec4-bcab-d926fa347208', '91e5c9f2-f456-4906-8834-928896931964', 1, 'Reconcile the planning note against the actual delivery logs to code only the fractions genuinely documented as delivered DURING this specific stay, since coding should reflect what was actually performed during the encounter being coded, not the overall treatment plan''s total regardless of how many fractions actually occurred during this particular admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e392462-8ffc-4d9a-ba83-d702f502d1ed', '91e5c9f2-f456-4906-8834-928896931964', 2, 'Code the delivery logs only, ignoring the planning note''s relevance entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64898077-1c66-466b-904e-2dc0eb138e75', '91e5c9f2-f456-4906-8834-928896931964', 3, 'Radiation fraction counts are never reconciled against planning documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12ee4a52-a28b-44b4-bf36-c59560466a97', '0f74f01f-7090-4735-b4c0-9e0cf2dcbbbd', 0, 'Insufficient documentation, since only physician-authored notes may ever be used for any newborn data element');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('621b32f8-6bf5-4bdd-a00b-dbb73f3916b0', '0f74f01f-7090-4735-b4c0-9e0cf2dcbbbd', 1, 'Generally sufficient, since Apgar scoring is a recognized nursing/delivery-team-documented data element (consistent with the same type of documentation-source exception discussed for other structured measurements like BMI and wound staging), not requiring independent physician restatement to be used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('141e7189-5c9f-446c-8577-bf03db100b49', '0f74f01f-7090-4735-b4c0-9e0cf2dcbbbd', 2, 'Sufficient only if the Apgar score is exactly 10');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87a4b7b2-af9e-4b2f-a7fd-e05acb735737', '0f74f01f-7090-4735-b4c0-9e0cf2dcbbbd', 3, 'Irrelevant, since Apgar scores are never a coding element in ICD-10-CM');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('063db411-d8f7-452a-b92d-56eaa2f37ac7', 'f07a2eb8-1c8c-47cb-9a70-91ff1bafb91c', 0, 'Automatically code the injury as assault based solely on the social worker''s concern, without any physician determination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('549c77ed-8dc1-41c4-9c90-a3f5de531127', 'f07a2eb8-1c8c-47cb-9a70-91ff1bafb91c', 1, 'Recognize this as a genuine documentation gap/conflict regarding external-cause intent requiring further physician clinical assessment/documentation or a compliant query, since a social work concern (while an important clinical signal, especially for suspected abuse/neglect protocols) doesn''t itself constitute a physician''s clinical determination of injury intent for coding purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c5d363a-6123-46c0-883d-8817462eb736', 'f07a2eb8-1c8c-47cb-9a70-91ff1bafb91c', 2, 'Ignore the social work note entirely as irrelevant to coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9e088338-dcf1-4cd6-afea-28959b580b4c', 'f07a2eb8-1c8c-47cb-9a70-91ff1bafb91c', 3, 'Automatically code the injury as accidental, overriding the social work concern without further review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a98b51a-928c-457d-9a6a-9d0a17479779', '4cba1e4b-cf71-4d2c-9d31-8efe710ea1fc', 0, 'Telehealth encounters can never support diagnosis coding of any kind, regardless of what was documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e26da14b-084a-4cad-bab1-1e088e84bb64', '4cba1e4b-cf71-4d2c-9d31-8efe710ea1fc', 1, 'The same documentation-sufficiency principles apply regardless of visit modality — a telehealth encounter''s documentation should still reflect actual clinical evaluation/management of a condition to support its coding, just as an in-person visit''s documentation would, without a different or lower documentation standard simply because the encounter occurred virtually');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8275d2e2-1900-4c2f-b42a-044076eed506', '4cba1e4b-cf71-4d2c-9d31-8efe710ea1fc', 2, 'Telehealth encounters automatically qualify every chronic condition on the problem list for HCC capture with no evaluation-specific documentation needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b7d3f53-59a5-41e4-abdc-f1b7583be22c', '4cba1e4b-cf71-4d2c-9d31-8efe710ea1fc', 3, 'Only in-person visits may ever be used for HCC-relevant diagnosis capture');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3af4a3b0-60af-4bce-be47-21add15275a8', '4319a455-bd6a-438a-92df-b2bc853baae2', 0, 'Automatically adopt the outside summary''s characterization without any review by the receiving facility''s own treating physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('611983fa-eed3-4f72-adb6-cb118813bec0', '4319a455-bd6a-438a-92df-b2bc853baae2', 1, 'Recognize that the receiving facility''s own coding should generally be based on ITS OWN treating physician''s clinical documentation — an outside record can inform clinical decision-making and may be incorporated if the receiving physician reviews and adopts it into their own documented assessment, but the receiving facility''s coding shouldn''t rely solely on an unverified outside patient-reported history without the treating physician''s own clinical acknowledgment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0cc76c1-7d84-4d42-a122-795d14cd0fc9', '4319a455-bd6a-438a-92df-b2bc853baae2', 2, 'The outside summary alone is always sufficient regardless of whether the receiving physician ever reviews or references it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8115b5cd-b1ac-4888-a834-2bbb5dc304ca', '4319a455-bd6a-438a-92df-b2bc853baae2', 3, 'Outside transfer summaries can never be used or referenced by a receiving facility under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdb12862-49e2-48f3-be12-0242d77bf3d3', '80776317-d755-4546-8835-78e1a4af1550', 0, 'Timestamp/release-timing data has no relevance to information-blocking compliance monitoring');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad244cc6-0543-43b0-91e9-5cefd29dae01', '80776317-d755-4546-8835-78e1a4af1550', 1, 'Tracking metadata such as note-release timing supports a facility''s ability to demonstrate compliance with timely patient-access expectations under information-blocking rules, and to identify/correct any systemic delays inconsistent with those expectations — an practical HIM documentation/monitoring practice connecting Domain 2-adjacent recordkeeping to Domain 4/5 compliance obligations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c6b8cc4-b7e6-4eb8-890a-cc0176b04ab2', '80776317-d755-4546-8835-78e1a4af1550', 2, 'Only IT departments need to track any timing-related metadata; HIM has no role');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82824d5c-957d-41f4-bec0-2df32cc1ea8a', '80776317-d755-4546-8835-78e1a4af1550', 3, 'Timestamp data is relevant only for billing purposes, never compliance monitoring');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('451d0039-0534-4fc2-9a9e-bf1c535181cd', 'e998e8ac-581d-4b1f-87a9-0c69a81e56a5', 0, 'No special system consideration is needed; Part 2 and non-Part-2 records may always be freely intermixed and disclosed identically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ae59bc9-7560-4acd-bb2d-6f48f4ce0172', 'e998e8ac-581d-4b1f-87a9-0c69a81e56a5', 1, 'The system/organization should have a way to identify and appropriately segregate or flag Part 2-covered records/data so that the heightened consent/redisclosure requirements can actually be applied correctly when those specific records are involved, rather than treating all EHR content as subject to identical, undifferentiated disclosure rules');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ff66dde-69cb-4a25-bd6a-16217e30b75b', 'e998e8ac-581d-4b1f-87a9-0c69a81e56a5', 2, 'Part 2-covered records can never be stored in the same EHR system as other records under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d633da0a-d0ff-406f-ac1a-417835eb4fe9', 'e998e8ac-581d-4b1f-87a9-0c69a81e56a5', 3, 'Only paper-based Part 2 records exist; electronic storage of Part 2-covered information is prohibited entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45449696-7ee1-48e8-a2ba-53f72c074e2b', '122e5d8d-be72-439b-8a2d-541fa0c0c618', 0, 'Code directly from the raw genetic test result as if it were the physician''s own clinical interpretation, without waiting for or seeking the physician''s documented interpretation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7aa4a00-820e-4573-92a9-744333d95709', '122e5d8d-be72-439b-8a2d-541fa0c0c618', 1, 'Recognize that a raw test result alone (without the ordering/treating physician''s own documented clinical interpretation) may not be sufficient to support certain diagnosis coding decisions dependent on that interpretation — holding for the physician''s documentation or querying, consistent with the general principle that a raw test result isn''t automatically equivalent to a physician''s diagnostic determination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de649fc0-9305-4803-98eb-b8a53984f06d', '122e5d8d-be72-439b-8a2d-541fa0c0c618', 2, 'Never code any encounter where a genetic test result exists in the chart');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd802695-a58a-407e-80c9-0c7c8917705e', '122e5d8d-be72-439b-8a2d-541fa0c0c618', 3, 'Assume the physician''s interpretation will always match the coder''s own independent reading of the raw result');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b94a0f41-88e0-48cd-a1df-63b23ae70ab1', 'f8dcb29e-9a0a-4189-97d2-1c1c7ad7c0ca', 0, 'Simply whether the coder''s own suspected severity level is correct, phrased as a yes/no confirmation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('447b691d-815f-4598-8b5a-7838b8ac604c', 'f8dcb29e-9a0a-4189-97d2-1c1c7ad7c0ca', 1, 'The episode pattern (single vs. recurrent), current severity, and remission status, presented as genuine multiple-choice options (including an ''unable to determine'' option) based on the documented clinical picture, rather than suggesting one specific answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ed2055d-b39b-46c5-a83c-96a520cba692', 'f8dcb29e-9a0a-4189-97d2-1c1c7ad7c0ca', 2, 'Only whether medication was prescribed, with no reference to the actual diagnosis specificity needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7274169e-79dc-4f11-b381-50f0b4f4ec51', 'f8dcb29e-9a0a-4189-97d2-1c1c7ad7c0ca', 3, 'Whether the patient''s insurance covers a higher level of care, unrelated to the clinical diagnosis itself');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('862a0173-4280-425d-967d-679baa236dab', 'a3331e10-aa0a-41a4-9603-db1100baca71', 0, 'Intent should never be queried under any circumstances due to its sensitivity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb562006-a2eb-41d4-ab70-8ae859341b20', 'a3331e10-aa0a-41a4-9603-db1100baca71', 1, 'A non-leading, clinically-framed query presenting the documentation ambiguity and asking the physician to clarify intent based on their own clinical assessment (not the coder''s speculation) remains appropriate and follows the same non-leading construction principles as any other query — sensitivity of the topic doesn''t exempt it from being addressable via compliant query construction, though particular care in wording is warranted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38e1fde5-dc15-4d06-99aa-835f9618b6f3', 'a3331e10-aa0a-41a4-9603-db1100baca71', 2, 'Only law enforcement, never a coder or CDI specialist, may ever raise this question');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8b6f95b-5729-4e17-8042-5246ee53374f', 'a3331e10-aa0a-41a4-9603-db1100baca71', 3, 'The coder should independently determine intent based on the police report without ever involving the treating physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a685bdd2-1e3a-4335-bd66-359a2de97427', 'ed202a51-f901-4aa1-a2b5-1cb920b68f14', 0, 'Substance use disorder severity can never be queried due to confidentiality protections');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1304a712-7527-4abb-9f2c-fe0483ae2fa5', 'ed202a51-f901-4aa1-a2b5-1cb920b68f14', 1, 'A compliant, non-leading query for clinical specificity remains appropriate — confidentiality protections (like 42 CFR Part 2) govern DISCLOSURE of substance use treatment records to outside parties, not whether a treating facility''s own coder/CDI staff may appropriately query the treating physician for documentation clarity needed for accurate coding of that same treatment episode');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('859668cd-ef07-4062-a520-5bc321acb4e2', 'ed202a51-f901-4aa1-a2b5-1cb920b68f14', 2, '42 CFR Part 2 prohibits all internal coding/CDI activity related to substance use disorders');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6dc605b-3635-40fb-b721-8c5554f897d6', 'ed202a51-f901-4aa1-a2b5-1cb920b68f14', 3, 'Only physicians specializing in addiction medicine may ever be queried about substance use disorders');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('393cbf9e-1e39-4a64-90bd-2902f61657ca', '7e61e2ea-62a1-4a86-bdbc-fac8ab2ac2a0', 0, 'Simply which number the physician prefers to use, with no clinical framework offered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12ac79d8-9f26-485e-929a-7ab71b19be08', '7e61e2ea-62a1-4a86-bdbc-fac8ab2ac2a0', 1, 'The current, most clinically accurate gestational age determination based on all available dating information (LMP, early ultrasound, clinical exam), presented as an open clinical question rather than suggesting a specific predetermined answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9d7fb66-fa5a-4980-9a66-08804f0bc62d', '7e61e2ea-62a1-4a86-bdbc-fac8ab2ac2a0', 2, 'Whether the patient''s due date should be changed on her insurance paperwork');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('681d282a-e34e-4e4a-8d46-1cce9a2a0634', '7e61e2ea-62a1-4a86-bdbc-fac8ab2ac2a0', 3, 'Nothing; gestational age discrepancies should never be queried');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b1270397-d362-4dbc-93cc-eb76cc05a9c0', '9e385410-a836-4a8f-952a-9de06e2edc1b', 0, 'A query presenting the specific documented symptom pattern and asking the physician to clarify whether an additional diagnosis (with multiple genuine options, including ''not clinically significant'' or ''insufficient information to determine'') is warranted, without suggesting anxiety specifically as the presumed answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f63df4f-dc02-4a76-81cc-cf93fc262700', '9e385410-a836-4a8f-952a-9de06e2edc1b', 1, 'A query stating ''please add anxiety disorder to the diagnosis list'' with only a yes/no response option');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b91d7e9a-b792-492b-80e9-a840a604051c', '9e385410-a836-4a8f-952a-9de06e2edc1b', 2, 'No query should ever be sent regarding behavioral health diagnostic ambiguity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bfed82d1-4ab1-4765-b90a-fa32d9f65621', '9e385410-a836-4a8f-952a-9de06e2edc1b', 3, 'A query directed at the patient rather than the treating physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01038e01-5530-4177-a1e8-e5f1742b1e00', '2b54c47b-9fcd-42e4-a7ea-8fd68af4ef78', 0, 'A non-leading query presenting the documentation ambiguity and asking the performing physician to clarify the actual donor-source type used, since this is a genuine, clinically-determinable fact the physician/procedure team would know with certainty');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e42a3554-cc01-4077-89cc-f1e6bc41dd62', '2b54c47b-9fcd-42e4-a7ea-8fd68af4ef78', 1, 'This detail should never be queried since it''s considered a purely administrative data point');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45bd0912-263d-4a78-953e-5732ccfe0f24', '2b54c47b-9fcd-42e4-a7ea-8fd68af4ef78', 2, 'The coder should assume autologous by default, since it''s the most common type, without querying');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('515af2ea-8234-499c-9383-f0c8346123fc', '2b54c47b-9fcd-42e4-a7ea-8fd68af4ef78', 3, 'Donor-source queries must always be directed to the hospital''s blood bank, never the performing physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39038fdf-e4fa-4321-b7d6-9a38f3e43018', '2a197311-93ed-4c3e-bf48-047fb789235e', 0, 'The query should be worded to elicit the physician''s own clinical assessment of intent based on the clinical presentation and any available history, using non-leading, multiple-option framing (including accidental, self-harm, assault, undetermined) — the safety-planning implications of a self-harm determination make accurate, non-presumptive clarification especially important, not a reason to avoid querying');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6f1bb7e-5b9b-4b0a-9564-bbff7750f620', '2a197311-93ed-4c3e-bf48-047fb789235e', 1, 'Self-harm intent should never be queried since asking about it might upset the physician');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1431101d-b04b-41aa-95a9-b14d9f539ae9', '2a197311-93ed-4c3e-bf48-047fb789235e', 2, 'The query should presume self-harm and simply ask the physician to confirm it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a02931ac-c0d8-46ea-aa6d-6c0e7d9bc13a', '2a197311-93ed-4c3e-bf48-047fb789235e', 3, 'Only a psychiatrist, never the treating ED physician, may ever be asked to clarify intent');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f93899e7-8967-4dd5-803a-5f8e1d7c9226', '5ede3762-cb0a-47a2-9197-c8bda40ccd8b', 0, 'A non-leading query clarifying the current diagnostic certainty (confirmed vs. suspected/pending workup) is appropriate when the record doesn''t clearly establish this, since coding specificity may depend on whether a diagnosis is confirmed versus still being worked up — particularly relevant given that the INPATIENT uncertain-diagnosis guideline may or may not appropriately apply depending on the clinical documentation specifics');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ab7116c-f943-450e-96ed-175e8f173950', '5ede3762-cb0a-47a2-9197-c8bda40ccd8b', 1, 'Congenital anomaly diagnoses should never be queried regardless of documentation clarity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('057e2848-31bd-4568-9f08-4ab114860ae3', '5ede3762-cb0a-47a2-9197-c8bda40ccd8b', 2, 'Only the parents, never the treating physician, should be asked to clarify a newborn''s diagnostic status');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e382a747-a6bb-43b2-8056-a25dd5bce655', '5ede3762-cb0a-47a2-9197-c8bda40ccd8b', 3, 'Diagnostic certainty is irrelevant to newborn coding specificity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f4321e4-be81-4c3b-8eb8-10caa603c28b', '25065821-8ae4-4852-a72e-beec58ab9e83', 0, 'Automatically use the physician''s query-response percentage with no further review, since it''s the most recent documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('312c813f-bbb6-4703-bfd4-d4c63a264b5c', '25065821-8ae4-4852-a72e-beec58ab9e83', 1, 'Recognize a possible ongoing documentation inconsistency and consider following up for clarification/reconciliation between the query response and the underlying body-site documentation, since a coder should still apply reasonable documentation-review judgment even after receiving a query response, particularly where a mathematical/clinical inconsistency is apparent from the record itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('995cf8bd-9d25-4ddd-8c7e-466e2ecd93b5', '25065821-8ae4-4852-a72e-beec58ab9e83', 2, 'Ignore the query response entirely and calculate TBSA independently using only the coder''s own estimation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7469ed1-3f02-4829-b464-1d6f685e2b49', '25065821-8ae4-4852-a72e-beec58ab9e83', 3, 'Refuse to code the burn TBSA percentage at all once any inconsistency is noticed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d838118-8f73-4cf6-8cc5-d959104de3d1', '49908479-6076-4774-b696-306e119089ca', 0, 'The query itself, directed to the treating physician for purposes of accurately documenting/coding that same treatment episode, follows the same non-leading compliance principles as any other query — 42 CFR Part 2''s disclosure restrictions govern sharing that information with THIRD PARTIES outside the treating context, not the internal query/documentation-clarification process within the treating facility for its own coding of that same episode');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60ab28f7-8e79-4203-a467-aa1b69c0e8cc', '49908479-6076-4774-b696-306e119089ca', 1, 'Any query touching Part 2-covered information is automatically prohibited regardless of purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87e32e7b-8304-4288-ac99-5099a4c48241', '49908479-6076-4774-b696-306e119089ca', 2, 'Part 2 requires a completely different, unique query format not used for any other type of diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1719b58b-5a5d-42ea-8041-be1995990da0', '49908479-6076-4774-b696-306e119089ca', 3, 'Only addiction medicine specialists may ever query about Part 2-covered conditions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('831e6bec-6b02-43cb-b257-a500968f1624', 'b1a84b25-85b4-4af9-a9f3-8d8af3b1450f', 0, 'A law prohibiting the offer, payment, solicitation, or receipt of remuneration to induce or reward referrals of federal healthcare program business');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0011f1ee-e458-4d73-af43-57734b2dcc98', 'b1a84b25-85b4-4af9-a9f3-8d8af3b1450f', 1, 'A billing code set used for ambulance transport claims');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0931d281-7e45-4002-be11-5418018f52d0', 'b1a84b25-85b4-4af9-a9f3-8d8af3b1450f', 2, 'A rule governing only hospital cafeteria pricing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5dfd7e32-3e60-437c-9176-11c81a61857f', 'b1a84b25-85b4-4af9-a9f3-8d8af3b1450f', 3, 'A HIPAA Privacy Rule provision, unrelated to fraud/abuse law');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d155b30-8dd0-4fa4-b88e-21d589a587c8', '0ef59149-6237-40fd-932d-e1915d3c1a5c', 0, 'A law prohibiting physicians from referring Medicare/Medicaid patients for certain designated health services to an entity with which the physician (or an immediate family member) has a financial relationship, absent an applicable exception');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31429431-0acb-4bf9-a210-8a27b5841a59', '0ef59149-6237-40fd-932d-e1915d3c1a5c', 1, 'A rule governing hospital parking facilities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eccc2aff-7bd8-4a21-95c8-acd1b7ee6ec1', '0ef59149-6237-40fd-932d-e1915d3c1a5c', 2, 'The same law as the Anti-Kickback Statute, using a different name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bdd0bdd3-0880-4d74-88b1-a386a2c55d8f', '0ef59149-6237-40fd-932d-e1915d3c1a5c', 3, 'A law that applies only to non-physician practitioners, never physicians');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c97be9b2-d3a6-4c9b-9c7d-9a63f4fcc160', 'ae8ac1a9-d35d-47c8-a8f2-d17d0d4bcfa4', 0, 'There is no meaningful intersection; AKS/Stark are entirely unrelated to coding/HIM functions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8aab5997-d41b-48ed-a97f-e72d8990430e', 'ae8ac1a9-d35d-47c8-a8f2-d17d0d4bcfa4', 1, 'Coding/billing data (e.g., referral patterns reflected in claims, or unusual utilization patterns tied to a specific referring relationship) can sometimes surface as evidence in AKS/Stark investigations, making general compliance-program awareness of these frameworks relevant context for HIM/coding compliance staff even without direct contract-negotiation involvement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17531d5a-dd7b-4138-9b8d-2f66db7acd6e', 'ae8ac1a9-d35d-47c8-a8f2-d17d0d4bcfa4', 2, 'AKS/Stark compliance is solely determined by which ICD-10-CM codes are used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ac960c5-fd2e-4b24-ac56-99679b6f9b61', 'ae8ac1a9-d35d-47c8-a8f2-d17d0d4bcfa4', 3, 'Only billing department staff, never HIM/coding staff, need any awareness of these laws');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('281dedc7-6f1b-4a40-bda2-a1aff8856aae', '1d126bbe-53cb-4721-a730-d18500a6f42d', 0, 'Practices by healthcare providers, health IT developers, and health information exchanges that unreasonably interfere with the access, exchange, or use of electronic health information, absent an applicable exception');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb409456-e6c2-4489-9185-7adde9d7a594', '1d126bbe-53cb-4721-a730-d18500a6f42d', 1, 'Any use of electronic health records whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f154916c-52df-4251-9e53-fd2e5cfa7eed', '1d126bbe-53cb-4721-a730-d18500a6f42d', 2, 'Only prohibits blocking access to a patient''s own billing records, not clinical records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f02ae6b-4d8b-4576-8a8c-dd46b58cadf5', '1d126bbe-53cb-4721-a730-d18500a6f42d', 3, 'A rule requiring all patient data to be shared publicly on the internet with no access restrictions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('823e818f-9e10-4fd1-af1d-21d19a7fba48', '08a47200-5bc1-4d89-929d-986c895f8675', 0, 'Information-blocking rules have no relevance to HIM release-of-information or patient-portal practices');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34f9baa8-6fad-4939-bbf4-d03206896e83', '08a47200-5bc1-4d89-929d-986c895f8675', 1, 'HIM departments should ensure release-of-information/patient-access practices and timelines don''t create unreasonable delays or barriers to a patient''s timely access to their own EHI (including certain categories of clinical notes now generally expected to be readily accessible), consistent with information-blocking requirements, while still applying legitimate, permitted exceptions where they genuinely apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16379e68-d5b9-4442-b96a-36d5c51079b3', '08a47200-5bc1-4d89-929d-986c895f8675', 2, 'All clinical notes must always be withheld from patients regardless of information-blocking rules');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('202bcb2c-a9cd-44ec-837b-2b9c4c05acaa', '08a47200-5bc1-4d89-929d-986c895f8675', 3, 'Information blocking rules apply only to insurance companies, never healthcare providers or their HIM departments');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7d324bd-1101-4403-ab6c-987fcf339247', '1f2d620e-0aa0-4ba1-8e4b-72602029d677', 0, 'Withholding information simply because releasing it would be administratively inconvenient for staff');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4169108-f96b-4dcf-9070-dbb128631b6c', '1f2d620e-0aa0-4ba1-8e4b-72602029d677', 1, 'Recognized exceptions include categories such as preventing harm (a narrowly defined, documented risk-of-harm standard), legitimate privacy protections consistent with applicable law, and reasonable security measures — each with specific defined conditions that must actually be met, not a generic ''we''d rather not share it'' justification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('831f2f4d-9538-4dcd-8110-e5b808ecf8c2', '1f2d620e-0aa0-4ba1-8e4b-72602029d677', 2, 'There are no legitimate exceptions; all information must always be shared with zero exceptions under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53ff54b1-3d1c-4ee7-826b-21e97e65a467', '1f2d620e-0aa0-4ba1-8e4b-72602029d677', 3, 'Cost savings for the facility is a recognized information-blocking exception');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e8f1514-eda7-4683-b4b3-607969040be1', 'bfbf5ba0-1ce1-4f94-bc16-3e85f6eddb25', 0, 'HIPAA and 42 CFR Part 2 are identical, so no additional consideration beyond standard HIPAA compliance is ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca1198b4-07bc-4ddb-832a-7c82cae1621f', 'bfbf5ba0-1ce1-4f94-bc16-3e85f6eddb25', 1, 'Substance use disorder treatment records maintained by a federally-assisted program may be subject to 42 CFR Part 2''s generally MORE restrictive consent/disclosure requirements in addition to HIPAA, meaning HIM staff handling such records need awareness of both frameworks and should apply whichever is more protective/restrictive where they differ');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('134271b2-9989-4961-ae22-bc12939cb734', 'bfbf5ba0-1ce1-4f94-bc16-3e85f6eddb25', 2, '42 CFR Part 2 completely replaces HIPAA for any behavioral health record, making HIPAA irrelevant to those records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('edafa079-3e6c-4298-9b86-d03e28be78c3', 'bfbf5ba0-1ce1-4f94-bc16-3e85f6eddb25', 3, 'Only research institutions are subject to 42 CFR Part 2, never treatment-providing facilities');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('62cc3861-836c-4a12-85aa-eb464ebe8ad0', '315d8f28-dcb4-4339-bb4b-35d5cedd8cab', 0, 'No such distinction is practically necessary since the two frameworks impose identical requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c54043fe-6c1c-4588-b32a-02f1e1b0800d', '315d8f28-dcb4-4339-bb4b-35d5cedd8cab', 1, 'Because 42 CFR Part 2''s heightened consent/redisclosure restrictions apply specifically to substance use disorder treatment information from a covered program (not necessarily every behavioral health record broadly), clear internal policy helps staff correctly apply the appropriate, more restrictive handling only where it actually applies — avoiding both under-protection (a real compliance risk) and unnecessary over-restriction of records that don''t actually meet Part 2''s specific coverage criteria');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64f102ef-6dfa-4645-a5d6-ecb565cfcd1d', '315d8f28-dcb4-4339-bb4b-35d5cedd8cab', 2, 'Every single behavioral health record in existence is automatically covered by 42 CFR Part 2 with no distinction ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f37ca2d6-1d70-4e79-976a-7439e22a82ad', '315d8f28-dcb4-4339-bb4b-35d5cedd8cab', 3, 'This distinction is relevant only to state licensing boards, never to a facility''s own internal compliance policy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a408b41c-9e54-4823-bfb7-ba7280cf86b3', 'bd3b0d7b-a2b9-449d-b1c6-f15a0cf5aa51', 0, 'Both laws require identical proof of specific intent to violate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('74070a84-4a14-418e-b53e-93c5e2915c4a', 'bd3b0d7b-a2b9-449d-b1c6-f15a0cf5aa51', 1, 'AKS is a criminal statute generally requiring proof of intent (knowing and willful conduct) to establish a violation, while Stark Law is a strict-liability civil statute that can be violated regardless of intent — a financial relationship failing to meet an exception can trigger Stark liability even without any intent to violate the law');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abb925b7-bec7-45d8-85ba-6ce67d252ca6', 'bd3b0d7b-a2b9-449d-b1c6-f15a0cf5aa51', 2, 'Stark Law requires proof of intent, while AKS is a strict-liability statute');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('455b2d2d-9ffe-4ca1-838b-36c5c03fe411', 'bd3b0d7b-a2b9-449d-b1c6-f15a0cf5aa51', 3, 'Neither law has ever been distinguished by an intent requirement; they are functionally identical in this respect');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba6a8d1c-162a-4aa7-928d-2070d590f1d9', 'a88d9356-821d-4ab6-a518-5d23015d7959', 0, 'A safe harbor is a specific, defined arrangement structure that, if fully satisfied, protects the arrangement from AKS liability — arrangements that don''t fit neatly into a safe harbor aren''t automatically illegal, but lose that specific protection and require case-by-case risk analysis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('053c07e4-d3cf-4f28-bc43-ad8d94a2d02d', 'a88d9356-821d-4ab6-a518-5d23015d7959', 1, 'Safe harbors guarantee protection from all healthcare fraud laws, including Stark Law and the False Claims Act, automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8130f117-6361-448f-b009-35938ebff99c', 'a88d9356-821d-4ab6-a518-5d23015d7959', 2, 'Safe harbors apply only to hospital-employed physicians, never independent practitioners');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c40b92a-b6e5-4324-bfa2-1a3b9a7385cd', 'a88d9356-821d-4ab6-a518-5d23015d7959', 3, 'There are no safe harbors under AKS; every arrangement is automatically illegal unless specifically pre-approved by CMS');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2164efc-a14e-4b79-b2ac-85945a768b83', '0f986775-b73e-4601-bf32-8dd764fd9f51', 0, 'A comprehensive healthcare compliance program typically addresses the full range of fraud/abuse exposure areas relevant to the organization, and coding/billing data can intersect with AKS/Stark risk areas (e.g., unusual referral-linked billing patterns) — making baseline literacy across these adjacent frameworks part of a well-rounded compliance program, even though the frameworks address different specific conduct');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('301c1bb2-1c4c-423a-81d0-fd81bac49a63', '0f986775-b73e-4601-bf32-8dd764fd9f51', 1, 'AKS/Stark have zero connection to any coding/billing compliance program and should be handled by an entirely separate department with no coordination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b1730e0-2259-4c2d-9415-f681e0c15928', '0f986775-b73e-4601-bf32-8dd764fd9f51', 2, 'Only legal counsel needs any awareness of AKS/Stark; compliance officers should focus exclusively on coding accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dff14a9d-58ad-4bd9-89c3-727c5cad4bdb', '0f986775-b73e-4601-bf32-8dd764fd9f51', 3, 'AKS/Stark compliance is only relevant to insurance companies, never to provider organizations');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ea0e220-8c85-4cdf-af4d-831be0fb923f', 'e5baca52-4cf3-4478-b118-9559b7c88d08', 0, 'Any financial relationship between a physician and a designated health service entity is automatically exempt from Stark scrutiny');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e654c736-c8ba-4e93-aefd-30482c46a115', 'e5baca52-4cf3-4478-b118-9559b7c88d08', 1, 'Certain defined exceptions (e.g., bona fide employment relationships, fair-market-value compensation arrangements meeting specific structural requirements, in-office ancillary services meeting defined criteria) can permit a financial relationship to exist without violating Stark, when all of that specific exception''s conditions are actually met');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c53df9df-3186-4680-a659-00adab86be16', 'e5baca52-4cf3-4478-b118-9559b7c88d08', 2, 'There are no exceptions to Stark Law under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a560f29-393e-4bec-8477-dbbb4ba16e13', 'e5baca52-4cf3-4478-b118-9559b7c88d08', 3, 'Exceptions apply only to relationships involving nonprofit hospitals');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24ed8bb2-248a-440e-8c8b-e1a9d1bfc03f', 'c7621ac6-b66e-4802-a96c-50ecf7148b6a', 0, 'This has no connection whatsoever to HIM/coding compliance and shouldn''t be part of any HIM-relevant compliance training');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ab78a5c-a536-4a83-b20f-ac91bb21a6e6', 'c7621ac6-b66e-4802-a96c-50ecf7148b6a', 1, 'Physician compensation structured to reflect referral volume (rather than fair-market-value for actual services) is a core AKS/Stark risk pattern — while HIM/coding staff don''t set compensation, general awareness of why this specific risk pattern matters supports a coherent, organization-wide compliance culture that HIM/coding staff operate within');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85f00b9b-f85c-4506-8789-b9e7af8c2202', 'c7621ac6-b66e-4802-a96c-50ecf7148b6a', 2, 'Physician compensation arrangements are entirely unregulated and require no compliance consideration at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c65b45ce-dbf4-40de-bcb7-8a4fa3bfb425', 'c7621ac6-b66e-4802-a96c-50ecf7148b6a', 3, 'Only the finance department needs any awareness of this risk pattern');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d8d1456-fa84-467a-86cc-f6738ae6b56e', '652ba393-207a-424e-807a-3f3486270944', 0, 'There is no relationship; each operates completely independently with no overlap in enforcement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2a3ddfb-d0d6-4fbd-90ba-ef156fb5267c', '652ba393-207a-424e-807a-3f3486270944', 1, 'Claims submitted to federal healthcare programs that resulted from an underlying AKS or Stark Law violation can also give rise to False Claims Act liability, since such claims may be considered ''false'' by virtue of arising from an illegal referral arrangement — creating a compounding compliance exposure beyond the AKS/Stark violation itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88c1ee8d-c0a8-45cc-8d43-50804bc112ae', '652ba393-207a-424e-807a-3f3486270944', 2, 'The False Claims Act applies only to coding errors, never to referral-relationship violations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfe2d61a-4158-4bcb-a93c-3c4e2358e0f0', '652ba393-207a-424e-807a-3f3486270944', 3, 'AKS/Stark violations can never result in any False Claims Act exposure under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d203804-b615-43aa-8a71-ac8ffd0ade85', '9a762d42-f691-4a54-884e-2a745b58c18f', 0, 'Information-blocking liability requires proof of deliberate, malicious intent to harm patients specifically, with no lesser knowledge standard ever applicable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7880af15-9aa0-40a6-938b-3beaa17c6456', '9a762d42-f691-4a54-884e-2a745b58c18f', 1, 'Depending on the specific regulated actor category and provision, information-blocking analysis can involve a knowledge standard (e.g., knew or should have known a practice was likely to interfere with EHI access/exchange/use) rather than requiring proof of malicious intent — meaning a practice adopted without malicious intent can still potentially raise information-blocking concerns if it interferes with EHI access absent an applicable exception');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b0f7b2d-9846-4af6-8860-7db4a4d1f7b9', '9a762d42-f691-4a54-884e-2a745b58c18f', 2, 'Information-blocking rules apply a strict-liability standard identical to Stark Law, with zero knowledge element ever relevant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1c39b53-4d65-4160-b868-8d317dae16e4', '9a762d42-f691-4a54-884e-2a745b58c18f', 3, 'Knowledge standards are irrelevant to information-blocking analysis entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a0a4ef3-9439-4b1d-a2f3-5a1f3cae85f2', 'bd8add64-c260-4481-8630-bd1083310098', 0, 'No action is needed since behavioral health notes are always fully exempt from any release timing expectations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('630fbd22-fd32-46fe-a2e2-c91f5afa17be', 'bd8add64-c260-4481-8630-bd1083310098', 1, 'Review the specific applicable exceptions (e.g., genuine, case-by-case privacy/harm-prevention grounds) versus an overly broad blanket exemption, and correct the system configuration to apply exceptions only where they are actually, specifically warranted — consistent with the broader compliance principle that exceptions require case-specific application, not blanket categorical assumptions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0cfaf4d-13fd-4918-a622-1fe7914c04dc', 'bd8add64-c260-4481-8630-bd1083310098', 2, 'Immediately disable the entire patient portal system for all note types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1837b409-5eb5-49b4-85c2-0b6649e88956', 'bd8add64-c260-4481-8630-bd1083310098', 3, 'Ignore the issue since behavioral health information is never subject to information-blocking rules under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5512688f-e49a-4da8-8ba3-b43fe40d5c6d', 'f23b533c-5abf-440e-a92e-663e93f5e3e8', 0, 'No documentation of exception determinations is ever necessary or expected');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc549e5c-1d80-4524-8090-93d61174f98e', 'f23b533c-5abf-440e-a92e-663e93f5e3e8', 1, 'Maintaining a record of WHY a specific exception was applied in a given instance supports demonstrating that the exception was genuinely, case-specifically warranted (rather than a blanket/pretextual withholding), consistent with the general compliance-program principle of maintaining evidence that policies are being applied correctly and in good faith');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc8a24c8-05c8-45ef-b778-a1b05c9d8b14', 'f23b533c-5abf-440e-a92e-663e93f5e3e8', 2, 'Exception documentation is relevant only for financial/billing decisions, never information-access decisions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dda3d372-6e8d-4a76-96b5-248545f2a431', 'f23b533c-5abf-440e-a92e-663e93f5e3e8', 3, 'Only the patient, never the facility, bears any documentation burden regarding an exception determination');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a14a6fef-fbb6-4537-be5a-bf0a8705fcaf', '198cfbdc-aaab-48dc-a8af-c9fab9be60ef', 0, 'All actor categories are subject to completely identical requirements with no distinctions whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2cc3b69-654f-4af5-b3cc-3ca183f3f3e0', '198cfbdc-aaab-48dc-a8af-c9fab9be60ef', 1, 'The specific regulatory requirements and applicable exceptions can vary somewhat depending on which actor category a given organization falls into, meaning a HIM/compliance professional should understand which category(ies) apply to their own organization''s various roles/functions rather than assuming a one-size-fits-all rule set');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b941ba75-5fd6-4d4d-8be1-05343fca0a6c', '198cfbdc-aaab-48dc-a8af-c9fab9be60ef', 2, 'Actor category is a purely academic distinction with zero practical compliance implications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb375750-b666-461c-85ed-c5ad0a5764aa', '198cfbdc-aaab-48dc-a8af-c9fab9be60ef', 3, 'Only health IT developers are ever subject to information-blocking rules; providers and HINs/HIEs are exempt');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5638815-b958-4dfd-84e9-93138dcf8d6c', '699a8783-0bf7-46d1-adef-044b58e9ce1f', 0, 'Clinical staff alone are always fully equipped to make Part 2 disclosure determinations with zero legal/compliance input ever needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a2de7a1-d293-4d2e-b7c6-628e5031398a', '699a8783-0bf7-46d1-adef-044b58e9ce1f', 1, 'Part 2''s consent/redisclosure requirements involve specific legal criteria (e.g., valid consent scope, applicable court order provisions, or other narrow exceptions) that benefit from legal/compliance review alongside clinical judgment, given the heightened, technically detailed nature of Part 2''s requirements compared to standard HIPAA disclosure analysis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4826b93d-1765-437b-be45-969eb9e037ba', '699a8783-0bf7-46d1-adef-044b58e9ce1f', 2, 'Part 2 disclosure decisions are purely clinical matters with no legal/compliance dimension whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f84928dc-8dac-4415-a96e-7cd253405f6d', '699a8783-0bf7-46d1-adef-044b58e9ce1f', 3, 'Only patients themselves, never facility staff of any kind, may ever determine whether a Part 2 disclosure is appropriate');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8d93597-2d9c-47cd-8d34-52da84cb41fb', 'b23c5974-1fc7-47f1-8779-3941584ec5f8', 0, 'Legal/compliance review of physician agreements is unnecessary busywork with no real risk-mitigation value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50b9724c-a018-47b1-8144-f3c207a84a00', 'b23c5974-1fc7-47f1-8779-3941584ec5f8', 1, 'Because compensation structure and referral-relationship terms in physician agreements are exactly the subject matter Stark Law and AKS regulate, dedicated legal/compliance review before execution (rather than relying solely on department-level business negotiation) is a recognized, standard risk-mitigation practice for these specific, technically complex regulatory frameworks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7454a439-9d93-4e54-a445-7e9bd376de75', 'b23c5974-1fc7-47f1-8779-3941584ec5f8', 2, 'Only agreements exceeding $1 million in total value require any compliance review under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b85a21d-4f10-4141-a5a7-e371184fdaf8', 'b23c5974-1fc7-47f1-8779-3941584ec5f8', 3, 'Department-level staff are always more qualified than legal/compliance staff to assess Stark/AKS risk');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05cabc1e-1d17-4105-9c65-c13e559aabff', '43737966-8f77-40be-a036-1e9bf49fe9e6', 0, 'A standards-based application programming interface that enables patients to access their own health information (often including claims and clinical data) through third-party applications of their choosing, using standardized data formats (e.g., FHIR-based)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('361b4099-8b49-43fb-ab7d-9881bb9348e2', '43737966-8f77-40be-a036-1e9bf49fe9e6', 1, 'A proprietary, single-vendor-only tool with no standardization requirement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85d056f3-a213-42bb-aab4-b04f22c6ed65', '43737966-8f77-40be-a036-1e9bf49fe9e6', 2, 'An interface used exclusively by hospital billing departments, with no patient-facing function');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0bcc8b6-1b0e-48d6-8856-fd83466a8bc3', '43737966-8f77-40be-a036-1e9bf49fe9e6', 3, 'A system that only physicians, never patients, may use to access clinical data');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('469e16d9-ed82-41dc-9b2c-23d8c8b7623b', '9986bb10-067c-4e71-b614-7de1c3eea6cc', 0, 'A PDF export fully satisfies all interoperability/patient-access API requirements with no further standardization needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('841c5a5e-0475-4986-8b16-f3dd2cf1a3c2', '9986bb10-067c-4e71-b614-7de1c3eea6cc', 1, 'Standardized, structured data formats (like FHIR resources) enable patients'' chosen third-party applications to actually parse and use the data programmatically (e.g., aggregating records across multiple providers), which a static PDF export cannot support — this is the core distinction driving the API/standardized-format requirement beyond simple document access');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('50366b73-0800-4ce3-8b92-f294ca013926', '9986bb10-067c-4e71-b614-7de1c3eea6cc', 2, 'FHIR and PDF are functionally identical for all interoperability purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3245c10-df92-4cb0-91f5-85a0299624fc', '9986bb10-067c-4e71-b614-7de1c3eea6cc', 3, 'Structured data formats are only relevant to billing data, never clinical data, for patient access purposes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f62c2aed-2d1e-4427-add5-e6eaf8646ce4', '8d6d5a8d-6973-4e4e-a3b6-ef62b4a504f8', 0, 'HIM has no role whatsoever in interoperability compliance; it is purely a technical IT/software engineering matter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('039da82c-fe4a-4100-88d9-c7ab356d889d', '8d6d5a8d-6973-4e4e-a3b6-ef62b4a504f8', 1, 'HIM professionals contribute domain expertise on what constitutes appropriate release-of-information practice, applicable legitimate exceptions (e.g., genuine 42 CFR Part 2 or other legally-required withholding), and patient-access policy/workflow design — complementing the technical API implementation work IT handles');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('942f5ce6-fba0-41e4-bb5f-607d15945bdd', '8d6d5a8d-6973-4e4e-a3b6-ef62b4a504f8', 2, 'HIM''s only role is physically mailing paper records, with zero connection to electronic interoperability initiatives');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38b0a407-4043-484f-b00f-0938c0709135', '8d6d5a8d-6973-4e4e-a3b6-ef62b4a504f8', 3, 'Only compliance officers, never HIM professionals, may ever weigh in on information-blocking policy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35876de5-634d-4017-b347-19234e072e59', '5f86a2e5-113d-4149-b131-128e3546e9ba', 0, 'Interoperability/information-blocking regulations are permanently fixed and will never be updated once initially implemented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2f35601-9679-408c-a1c8-b81474b22826', '5f86a2e5-113d-4149-b131-128e3546e9ba', 1, 'Regulatory requirements and enforcement priorities in this area have continued to evolve (e.g., expanding scope of what data must be shared, updated exception criteria, phased implementation timelines), meaning ongoing monitoring — not a one-time compliance project — is the realistic expectation, similar to how annual code-set updates require ongoing (not one-time) attention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('536270c1-d14f-47fd-9442-d24fd919f7ae', '5f86a2e5-113d-4149-b131-128e3546e9ba', 2, 'Only the initial regulatory rollout mattered; nothing has changed or is expected to change since then');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('899fa051-f111-4579-8aa8-6a4991c8b8a8', '5f86a2e5-113d-4149-b131-128e3546e9ba', 3, 'Interoperability compliance, once achieved, transfers permanently to the EHR vendor with zero ongoing facility responsibility');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d445c72e-d001-4382-b5d5-489e8aaf31dd', 'c61e2166-7507-4c49-96f4-767c09787f70', 0, 'An HIE/HIN is simply another name for a single hospital''s internal EHR system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bbde88bd-644f-4c1e-8bc7-3899bdfc9b63', 'c61e2166-7507-4c49-96f4-767c09787f70', 1, 'An HIE/HIN facilitates the exchange of health information among multiple, often unaffiliated, participating organizations — functioning as connective infrastructure between individual providers/systems rather than being a single provider''s own internal record system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd99a032-7216-49b0-9973-35388dd188fb', 'c61e2166-7507-4c49-96f4-767c09787f70', 2, 'HIEs/HINs are prohibited from operating under current federal health IT policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a42e2963-15ab-49b4-94e5-9f1b6e6eceae', 'c61e2166-7507-4c49-96f4-767c09787f70', 3, 'HIE/HIN participation eliminates any individual participating organization''s own HIPAA obligations');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc8c8fbb-9e6c-4429-905a-522128fd4c53', 'e066fda8-dff7-428d-8385-54a03f146c52', 0, 'HIM professionals never need any interoperability-related vocabulary since this is purely a software engineering concern');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aaafec31-22a3-47ab-a829-096bd5e26b66', 'e066fda8-dff7-428d-8385-54a03f146c52', 1, 'Understanding foundational concepts (APIs, FHIR resources, patient access requirements) allows HIM professionals to meaningfully participate in cross-functional interoperability/compliance discussions, evaluate vendor claims, and contribute domain expertise to policy/workflow decisions — without needing to personally write code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('350d04fb-2b66-4377-8dd8-d3c70db79ce3', 'e066fda8-dff7-428d-8385-54a03f146c52', 2, 'HIM professionals must become certified software developers before contributing to any interoperability initiative');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cce322bf-448a-4026-981a-9afeb70e8518', 'e066fda8-dff7-428d-8385-54a03f146c52', 3, 'Interoperability terminology is relevant only to patients, never to HIM staff');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebce6142-4b3d-4565-ab49-f9683d581987', '5455fe1a-6715-41b2-aaea-c54591e3ba2b', 0, 'USCDI is an unrelated billing code set with no interoperability relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed67662e-dbb0-46a6-b0ad-cf8d2a0bdbd7', '5455fe1a-6715-41b2-aaea-c54591e3ba2b', 1, 'USCDI defines a standardized set of health data classes/elements expected to be made available for interoperable exchange (including via patient access APIs), providing a common baseline of what data should be accessible/exchangeable — expanding over successive versions to include more data types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c518ffbd-3ede-483f-a867-ac9271ca55e7', '5455fe1a-6715-41b2-aaea-c54591e3ba2b', 2, 'USCDI applies only to laboratory data, never clinical notes or other data types');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7f37545-85df-4eec-ae34-894c06325bc3', '5455fe1a-6715-41b2-aaea-c54591e3ba2b', 3, 'USCDI is a one-time, unchanging standard that has never been updated since its original publication');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('acf8ade1-09bc-451f-ae9f-7e0507d29ffa', 'ed1a121f-263c-4c2d-968e-cca16c9aa3a8', 0, 'No evaluation is needed; all vendors are assumed to be fully compliant automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fee6a3d4-c62a-477c-83c3-bb4cbef1c0a8', 'ed1a121f-263c-4c2d-968e-cca16c9aa3a8', 1, 'Reviewing the vendor''s certified health IT status (e.g., ONC Health IT Certification), their support for standardized data formats (FHIR/USCDI), and their own information-blocking compliance practices/attestations as part of the procurement evaluation, alongside the vendor''s general functional/technical fit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71e021de-2868-4d17-865c-286cdf771c50', 'ed1a121f-263c-4c2d-968e-cca16c9aa3a8', 2, 'Vendor interoperability compliance is solely the vendor''s legal responsibility with zero relevance to the purchasing organization''s own diligence');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8daa2760-c303-449b-bf8c-34d1cb65537e', 'ed1a121f-263c-4c2d-968e-cca16c9aa3a8', 3, 'Only price should be considered during vendor procurement, with compliance posture irrelevant');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17c3c97e-f234-4f1d-a586-eeb5da576581', 'aed35226-a850-44f4-bf3b-e989b08bc88a', 0, 'Legacy system challenges have no particular relevance to information-blocking compliance specifically, beyond the data-integrity concern already discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e124563f-ddc0-44e5-8869-e0a012a21062', 'aed35226-a850-44f4-bf3b-e989b08bc88a', 1, 'An organization relying on older systems that genuinely cannot support required standardized data exchange (FHIR/USCDI-based patient access, etc.) may need to evaluate whether this creates information-blocking exposure or whether a genuine infeasibility-based exception might apply — connecting the earlier legacy-system/data-migration discussion to the compliance-exception framework covered under Domain 4');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16776665-d299-415b-9590-4c10cd29ffbc', 'aed35226-a850-44f4-bf3b-e989b08bc88a', 2, 'Legacy systems are entirely exempt from all interoperability requirements regardless of circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1ab433b-f367-4b6c-922c-df040efaee06', 'aed35226-a850-44f4-bf3b-e989b08bc88a', 3, 'Only brand-new systems are ever subject to information-blocking requirements');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('455a4cb5-d034-490c-bceb-34f3e123e313', 'd19a9160-c944-480a-b3c9-d15a9f185b93', 0, 'These are four entirely unrelated, siloed topics with no meaningful connections to each other');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39057795-9224-4784-8eac-0f6cd13e16cc', 'd19a9160-c944-480a-b3c9-d15a9f185b93', 1, 'HIM/coding information technology competency increasingly spans not just using coding-support tools (encoder/CAC) but understanding how health information is exchanged (interoperability standards), protected (cybersecurity/Security Rule safeguards), and made accessible to patients (information-blocking/patient access APIs) — a broader, interconnected technology literacy relevant to modern HIM practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84837608-9241-4bde-8eb7-bdce596e1856', 'd19a9160-c944-480a-b3c9-d15a9f185b93', 2, 'Only the encoder/CAC topic is relevant to CCS-credentialed coders; the others apply exclusively to IT staff');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00147e70-e83a-4059-99d2-f75975ce8e3b', 'd19a9160-c944-480a-b3c9-d15a9f185b93', 3, 'Interoperability, cybersecurity, and information-blocking are all simply different names for the identical same requirement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
